import React, { useState, useEffect, useRef } from 'react';
import { StyleSheet, Text, View, TouchableOpacity, Image, StatusBar, Platform, TextInput, ScrollView, Alert, ViewStyle } from 'react-native';
import { CameraView, useCameraPermissions } from 'expo-camera';
import * as ImagePicker from 'expo-image-picker';
import * as FileSystem from 'expo-file-system';
import { StackNavigationProp } from '@react-navigation/stack';
import { RouteProp } from '@react-navigation/native';
import { RootStackParamList } from '../App';
import CustomIcon from '../components/CustomIcon';
import Logo from '../components/Logo';
import ProcessingIndicator from '../components/ProcessingIndicator'; // Added import
import { COLORS } from '../constants/theme';
import { LinearGradient } from 'expo-linear-gradient';
import { MaterialIcons } from '@expo/vector-icons';
import { useLocalization } from '../i18n/localizationContext';
import { analyzeEyeArea, analyzeHairScalpImages } from '../services/geminiService'; // Added import

type CameraScreenNavigationProp = StackNavigationProp<RootStackParamList, 'Camera'>;
type CameraScreenRouteProp = RouteProp<RootStackParamList, 'Camera'>;

type Props = {
  navigation: CameraScreenNavigationProp;
  route: CameraScreenRouteProp;
};

const CameraScreen: React.FC<Props> = ({ navigation, route }) => {
  const { t, currentLanguage } = useLocalization();
  const [permission, requestPermission] = useCameraPermissions();
  const [hasPermission, setHasPermission] = useState<boolean | null>(null);
  const [facing, setFacing] = useState('front');
  const [previewVisible, setPreviewVisible] = useState(false);
  const [capturedImage, setCapturedImage] = useState<any>(null);
  const [visitPurpose, setVisitPurpose] = useState<string>('');
  const [isEyeAnalyzing, setIsEyeAnalyzing] = useState(false);
  const [hairScalpImages, setHairScalpImages] = useState<any[]>([]);
  const [isHairScalpAnalyzing, setIsHairScalpAnalyzing] = useState(false);
  const [isCameraReady, setIsCameraReady] = useState(false);
  const cameraRef = useRef<CameraView>(null);
  const currentMode: 'facial' | 'eye' | 'hairScalp' | 'beforeAfter' = route?.params?.mode || 'facial';
  console.log('CameraScreen rendering. previewVisible:', previewVisible, 'capturedImage:', capturedImage, 'hasPermission:', hasPermission, 'currentMode:', currentMode);

  // Function to handle barcode scanning (empty implementation to prevent crash)
  const handleBarcodeScanned = () => {
    // Empty implementation 
    // This prevents the error by having a constant handler instead of conditional logic
  };

  const getFrameConfig = () => {
    // Initialize with common properties from faceFrameContainer
    let containerStyle: ViewStyle = {
      position: 'absolute', // Assuming this is always 'absolute' from styles.faceFrameContainer
      alignItems: 'center', // Assuming this is always 'center'
      justifyContent: 'center', // Assuming this is always 'center'
      // Default dimensions from the base faceFrameContainer style
      top: styles.faceFrameContainer.top,
      left: styles.faceFrameContainer.left,
      right: styles.faceFrameContainer.right,
      bottom: styles.faceFrameContainer.bottom,
    };
    let frameStyle: ViewStyle = styles.faceFrame;
    let tipTextKey = 'centerYourFace';
    let showCorners = true;

    switch (currentMode) {
      case 'eye':
        containerStyle = {
          ...containerStyle, // Keep common properties like position, alignItems, justifyContent
          top: styles.eyeFrameContainer.top,
          left: styles.eyeFrameContainer.left,
          right: styles.eyeFrameContainer.right,
          bottom: styles.eyeFrameContainer.bottom,
        };
        frameStyle = { ...styles.faceFrame, ...styles.eyeFrame };
        tipTextKey = 'centerYourEyes'; // Ensure this key is in your i18n files
        showCorners = true; // Show corners for a distinct rectangle
        break;
      case 'hairScalp':
        containerStyle = {
          ...containerStyle, // Keep common properties
          top: styles.hairScalpFrameContainer.top,
          left: styles.hairScalpFrameContainer.left,
          right: styles.hairScalpFrameContainer.right,
          bottom: styles.hairScalpFrameContainer.bottom,
        };
        frameStyle = { ...styles.faceFrame, ...styles.hairScalpFrame };
        tipTextKey = 'centerYourScalp'; // Ensure this key is in your i18n files
        showCorners = false;
        break;
      case 'facial':
        // containerStyle already defaults to faceFrameContainer dimensions
        frameStyle = { ...styles.faceFrame, ...styles.facialFrame };
        tipTextKey = 'centerYourFace';
        break;
      default:
        // Defaults to 'facial' style if mode is 'beforeAfter' or unexpected
        // containerStyle already defaults to faceFrameContainer dimensions
        frameStyle = { ...styles.faceFrame, ...styles.facialFrame };
        tipTextKey = 'centerYourFace';
        break;
    }
    return { containerStyle, frameStyle, tipText: t(tipTextKey), showCorners };
  };

  // Function to toggle camera facing
  const toggleCameraFacing = () => {
    setFacing(facing === 'front' ? 'back' : 'front');
  };

  useEffect(() => {
    (async () => {
      console.log('Requesting camera permission...');
      const cameraPermission = await requestPermission();
      const status = cameraPermission.status === 'granted';
      console.log('Camera permission granted:', status);
      setHasPermission(status);
    })();
  }, []);

  const takePicture = async () => {
    if (!cameraRef.current || !isCameraReady) return;
    try {
      const photo = await cameraRef.current.takePictureAsync({
        base64: true,
        quality: 0.7,
        exif: false, // Don't need EXIF data
      });

      console.log('Photo captured, has base64:', !!photo.base64);

      setPreviewVisible(true);
      setCapturedImage(photo);
    } catch (error) {
      console.error('Error taking picture:', error);
    }
  };

  const pickImage = async () => {
    try {
      const result = await ImagePicker.launchImageLibraryAsync({
        mediaTypes: ImagePicker.MediaTypeOptions.Images,
        allowsEditing: false,
        aspect: [3, 4],
        quality: 0.7,
        base64: true,
      });

      if (!result.canceled) {
        const selectedAsset = result.assets?.[0];
        if (selectedAsset) {
          let finalUri = selectedAsset.uri;
          let base64Data = selectedAsset.base64;

          if (Platform.OS !== 'web' && selectedAsset.uri.startsWith('file://')) {
            // Native platforms: continue with caching logic
            const imagesDir = FileSystem.cacheDirectory + 'images';
            const dirInfo = await FileSystem.getInfoAsync(imagesDir);
            if (!dirInfo.exists) {
              await FileSystem.makeDirectoryAsync(imagesDir, { intermediates: true });
            }
            const newCachedUri = imagesDir + '/' + selectedAsset.uri.split('/').pop();
            await FileSystem.copyAsync({ from: selectedAsset.uri, to: newCachedUri });
            finalUri = newCachedUri;

            if (!base64Data) {
              try {
                base64Data = await FileSystem.readAsStringAsync(finalUri, {
                  encoding: FileSystem.EncodingType.Base64,
                });
                console.log('Successfully read base64 data from selected image');
              } catch (readError) {
                console.error('Error reading selected image as base64 from cache:', readError);
                // Optionally, alert the user or handle the error appropriately
              }
            }
          } else if (Platform.OS === 'web') {
            // Web platform: use the URI and base64 directly from ImagePicker
            if (!base64Data && finalUri && finalUri.startsWith('data:')) {
                base64Data = finalUri.substring(finalUri.indexOf(',') + 1);
            } else if (!base64Data) {
                console.warn(`Base64 data not available for picked image on web, URI: ${finalUri}`);
            }
          } else {
            // This case handles non-file URIs on native platforms (unlikely for picker) or other unexpected scenarios.
            console.warn(`Unsupported URI type or platform for image picking: ${selectedAsset.uri}`);
            Alert.alert(
              t('invalidImageTitle'),
              t('invalidImageMessage'),
              [{ text: t('ok') }]
            );
            return; // Exit if the image can't be processed
          }

          // Ensure base64Data is not undefined before proceeding
          if (typeof base64Data === 'string' || (base64Data === null && Platform.OS !== 'web')) { // Allow null base64 for native if it was already null and not re-read
            setPreviewVisible(true);
            setCapturedImage({...selectedAsset, uri: finalUri, base64: base64Data});
          } else {
            console.error('Failed to obtain base64 data for the selected image on web or image is invalid.');
            Alert.alert(
              t('imageProcessingErrorTitle') || 'Image Error',
              t('imageProcessingErrorMessage') || 'Could not process the selected image. Please try again.',
              [{ text: t('ok') }]
            );
          }
        }
      }
    } catch (error) {
      console.error('Error picking image:', error);
    }
  };

  const retakePicture = () => {
    setCapturedImage(null);
    setPreviewVisible(false);
  };

  const handleAnalyze = async () => {
    if (!capturedImage || !capturedImage.uri) return;

    try {
      let base64Data = capturedImage.base64 || '';
      if (!base64Data && capturedImage.uri) {
        try {
          base64Data = await FileSystem.readAsStringAsync(capturedImage.uri, {
            encoding: FileSystem.EncodingType.Base64,
          });
          console.log('Successfully loaded base64 data from image file');
        } catch (readError) {
          console.error('Error reading image as base64:', readError);
        }
      }

      if (currentMode === 'eye') {
        setIsEyeAnalyzing(true);
        try {
          const analysisResult = await analyzeEyeArea(capturedImage.uri, visitPurpose);
          if (analysisResult) {
            navigation.navigate('Report', {
              analysisType: 'eye',
              imageUri: capturedImage.uri,
              eyeAnalysisResult: analysisResult,
              visitPurpose: visitPurpose,
            });
          } else {
            Alert.alert(t('error'), t('eyeAnalysisFailed'));
          }
        } catch (error: any) {
          console.error('Error during eye analysis process:', error);
          const errorMessage = error?.message || t('eyeAnalysisFailed');
          Alert.alert(t('error'), errorMessage);
        } finally {
          setIsEyeAnalyzing(false);
        }
      } else {
        navigation.navigate('Analysis', {
          imageUri: capturedImage.uri,
          base64Image: base64Data,
          visitPurpose: visitPurpose,
        });
      }
    } catch (error) {
      console.error('Error preparing image for analysis:', error);
    }
  };

  const handleEyeAnalyze = async () => {
    if (!capturedImage || !capturedImage.uri) return;
    setIsEyeAnalyzing(true); // Start loading

    try {
      // If capturedImage already has base64, use it
      let base64Data = capturedImage.base64 || '';

      // If no base64 data, try to read it from the file
      if (!base64Data && capturedImage.uri) {
        try {
          base64Data = await FileSystem.readAsStringAsync(capturedImage.uri, {
            encoding: FileSystem.EncodingType.Base64,
          });
          console.log('Successfully loaded base64 data for eye analysis');
        } catch (readError) {
          console.error('Error reading image as base64 for eye analysis:', readError);
          // Optionally show an error to the user
          return; 
        }
      }

      // Call the actual eye analysis service
      const analysisResult = await analyzeEyeArea(capturedImage.uri, visitPurpose);

      // Check if analysis was successful before navigating
      if (analysisResult) {
        // Navigate to ReportScreen with eye analysis results
        navigation.navigate('Report', {
          analysisType: 'eye', // Indicate this is an eye analysis report
          imageUri: capturedImage.uri,
          // base64Image: base64Data, // ReportScreen might not need base64
          eyeAnalysisResult: analysisResult, // Pass the eye results
          // Pass other relevant params if ReportScreen needs them for eye context
          visitPurpose: visitPurpose,
        });
      } else {
        // Handle case where analysisResult is null or undefined (error handled in service)
        Alert.alert(t('error'), t('eyeAnalysisFailed')); 
      }
    } catch (error: any) { // Catch specific error type if possible
      console.error('Error during eye analysis process:', error);
      // Use a more specific error message if available from the error object
      const errorMessage = error?.message || t('eyeAnalysisFailed');
      Alert.alert(t('error'), errorMessage); // Show specific error to user
    } finally {
      setIsEyeAnalyzing(false); // Stop loading
    }
  };

  const navigateToHome = () => {
    navigation.navigate('Home');
  };

  if (hasPermission === null) {
    return (
      <View style={styles.permissionContainer}>
        <CustomIcon name="camera" size={50} color={COLORS.primary.main} />
        <Text style={styles.permissionText}>{t('requestingPermission')}</Text>
      </View>
    );
  }

  if (hasPermission === false) {
    return (
      <View style={styles.permissionContainer}>
        <CustomIcon name="no-photography" size={50} color={COLORS.error.main} />
        <Text style={styles.permissionText}>{t('noAccessCamera')}</Text>
        <TouchableOpacity
          style={styles.permissionButton}
          onPress={() => navigation.goBack()}
        >
          <Text style={styles.permissionButtonText}>{t('goBack')}</Text>
        </TouchableOpacity>
      </View>
    );
  }

  console.log('Render conditions - previewVisible:', previewVisible, 'hasPermission:', hasPermission, 'isCameraReady:', isCameraReady);

  return (
    <View style={styles.container}>
      <StatusBar barStyle="light-content" backgroundColor={COLORS.primary.dark} />

      {previewVisible && capturedImage ? (
        <ScrollView style={styles.previewScrollContainer}>
          <View style={styles.previewContainer}>
            <Image
              source={{ uri: capturedImage.uri }}
              style={styles.cameraPreview}
            />
            <View style={styles.formContainer}>
              <View style={styles.formSection}>
                <Text style={styles.formLabel}>{t('purposeOfVisit')}</Text>
                <TextInput
                  style={styles.textInput}
                  placeholder={t('visitPurposeHint')}
                  placeholderTextColor={COLORS.gray[400]}
                  multiline
                  numberOfLines={3}
                  value={visitPurpose}
                  onChangeText={setVisitPurpose}
                  textAlignVertical="top"
                  blurOnSubmit={false}
                  autoCapitalize="sentences"
                />
              </View>
            </View>
            <View style={styles.buttonContainer}>
              <TouchableOpacity
                style={[styles.button, styles.secondaryButton]}
                onPress={retakePicture}
              >
                <Text style={[styles.buttonText, styles.secondaryButtonText]}>{t('retake')}</Text>
              </TouchableOpacity>
              <TouchableOpacity
                style={[styles.button, styles.primaryButton]}
                onPress={handleAnalyze}
                disabled={isEyeAnalyzing || isHairScalpAnalyzing}
              >
                <Text style={[styles.buttonText, styles.primaryButtonText]}>
                  {isEyeAnalyzing || isHairScalpAnalyzing ? t('analyzing') : 
                    currentMode === 'eye' ? t('startEyeAnalysis') : 
                    currentMode === 'hairScalp' ? t('startHairScalpAnalysis') : 
                    t('startAnalysis')}
                </Text>
              </TouchableOpacity>
            </View>
          </View>
        </ScrollView>
      ) : (
        <View style={styles.cameraContainer}>
          <CameraView
            ref={cameraRef}
            style={styles.camera}
            facing={facing as any} // Type casting to avoid error
            ratio="4:3"
            onBarcodeScanned={handleBarcodeScanned} // Always pass a handler
            onCameraReady={() => { 
              console.log('Camera is ready! Facing:', facing);
              setIsCameraReady(true);
            }}
            onMountError={(error: { message: string }) => { 
              console.error('CameraView Mount Error:', error.message);
            }}
          />
          {/* Overlay elements, now siblings, positioned absolutely */}
          <View style={styles.cameraOverlay}>
            {(() => {
              const { containerStyle, frameStyle, tipText, showCorners } = getFrameConfig();

              return (
                <View style={containerStyle}>
                  <View style={frameStyle}>
                    {showCorners && (
                      <>
                        <View style={[styles.corner, styles.topLeftCorner]} />
                        <View style={[styles.corner, styles.topRightCorner]} />
                        <View style={[styles.corner, styles.bottomLeftCorner]} />
                        <View style={[styles.corner, styles.bottomRightCorner]} />
                      </>
                    )}
                  </View>
                  <Text style={styles.frameText}>{tipText}</Text>
                </View>
              );
            })()}

            <TouchableOpacity
              style={styles.flipButton}
              onPress={toggleCameraFacing}
            >
              <CustomIcon name="flip-camera-ios" size={26} color="white" />
            </TouchableOpacity>
          </View>

          {/* Bottom button container, now a sibling, positioned absolutely */}
          <View style={styles.bottomButtonContainer}>
            <TouchableOpacity style={styles.pickButton} onPress={pickImage}>
              <MaterialIcons name="photo-library" size={28} color="white" />
            </TouchableOpacity>

            <TouchableOpacity style={styles.captureButton} onPress={takePicture}>
              <View style={styles.captureButtonInner} />
            </TouchableOpacity>

            <TouchableOpacity style={styles.homeButton} onPress={navigateToHome}>
              <MaterialIcons name="home" size={28} color="white" />
            </TouchableOpacity>
          </View>
        </View>
      )}

      {(isEyeAnalyzing || isHairScalpAnalyzing) && <ProcessingIndicator />}
    </View>
  );
};

